[{"kind": "sent", "timestamp": "2026-08-31 07:22:09.697000+00:00", "message_id": "<21c0afc7-beda-4ad3-969a-81739f53d1d2@onebodyclinics.com>", "body": "<div>Hey Udai,</div><br><div>I noticed your Afro Asian Insurance London office is about 4 min walk from our Fenchurch Street clinic.</div><br><div>Reason I'm writing: if Afro Asian Insurance gives you private health cover, physio is almost certainly included in it.&nbsp;Most people barely touch it. I run One Body LDN. 38 physio locations across London, 7,764 reviews at 4.9, and we see a lot of people from big companies like KPMG, Deloitte and PwC.</div><br><div>So if something's nagging like lower back from sitting, neck, shoulder, a knee that complains when you run, we'll do your provider side from start to finish. Booking and paperwork. Most people are surprised to find nothing comes out of pocket.</div><br><div>And if you haven't got cover, your first 55-minute session with hands-on treatment is on us anyway. Want me to send you the booking code? Just reply and it's yours.</div><br><div>Kind regards</div><div></div>", "from_email": "kurt.johnson@onebodyclinics.com", "to_email": "udaipatel@afroasian-insurance.com", "stats_id": "21c0afc7-beda-4ad3-969a-81739f53d1d2", "cc": ""}, {"kind": "sent", "timestamp": "2026-09-02 07:42:15.790000+00:00", "message_id": "<28352c5d-5ed5-4996-a31a-8e8fd80fbc9c@onebodyclinics.com>", "body": "<div>firstName - still happy to send that over if you want it.</div><br><div>Free 55-minute session at Fenchurch Street clinic, or we run it through your insurance if you'd rather. One word back and I'll sort it.</div><br><div>Kind regards</div><div><div>Kurt Johnson</div><div>Co-Founder @ One Body LDN</div></div><br>", "from_email": "kurt.johnson@onebodyclinics.com", "to_email": "udaipatel@afroasian-insurance.com", "stats_id": "28352c5d-5ed5-4996-a31a-8e8fd80fbc9c", "cc": ""}, {"kind": "reply", "timestamp": "2026-09-02 07:42:26+00:00", "message_id": "<27f2e8ad549a4007a0bab68d966edbdd@DBAPR01MB66